// Indexed-colour sprite drawing (atlas generated by tools/convert_assets.py) with day/night tint.
#ifndef SPRITES_H
#define SPRITES_H

#include <stdbool.h>

#include "atlasdata.h"
#include "daycycle.h"
#include "gfx.h"

int spr_find(const char *name);       // sprite id by name, -1 if unknown
const SprDef *spr_def(int id);        // never NULL for a valid id

void spr_set_tint(DayTint t);         // light multiplier for every following spr_draw(tinted = true)
bool spr_tint_active(void);
px spr_tint_px(px v);                 // tint a single colour (terrain tiles, ground effects)

// Draws sprite `id` with its anchor (feet) at (x, y). scale is 1 or 2; flip mirrors around the anchor.
void spr_draw(Canvas *c, int id, int x, int y, int scale, bool flip, bool tinted);
// Draws with the top-left corner at (x, y) (UI icons), never tinted.
void spr_icon(Canvas *c, int id, int x, int y);
// Average-ish colour of a sprite (used for the minimap).
px spr_color_at(int id, int u, int v);  // palette colour of pixel (u,v), 0 when transparent

#endif
